def retry_success(p, n):
    return 1 - (1 - p) ** n

def expected_calls(p, n):
    return sum(k * p * (1 - p) ** (k - 1) for k in range(1, n + 1))

print(retry_success(0.6, 3), expected_calls(0.6, 3))
